// Process world state update request
const worldData = $input.first().json;
const { 
  campaignId,
  action, // 'update', 'create', 'get', 'delete'
  locationChanges = [],
  npcChanges = [],
  factionChanges = [],
  questChanges = [],
  worldEvents = [],
  timelineEvents = []
} = worldData;

// Validate required fields
if (!campaignId || !action) {
  throw new Error('Missing required fields: campaignId, action');
}

// Prepare operation data
const operationData = {
  campaignId,
  action,
  timestamp: new Date().toISOString(),
  locationChanges,
  npcChanges,
  factionChanges,
  questChanges,
  worldEvents,
  timelineEvents,
  metadata: {
    processedBy: 'campaign-world-workflow',
    version: '1.0'
  }
};

return { json: operationData };

// Process world state changes and calculate derived values
const worldData = $input.first().json;
const {
  campaignId,
  locationChanges,
  npcChanges,
  factionChanges,
  questChanges,
  worldEvents,
  timelineEvents
} = worldData;

// Get current world state
let currentWorldState = {
  campaignId,
  locations: [],
  npcs: [],
  factions: [],
  quests: [],
  worldEvents: [],
  timelineEvents: [],
  currentInGameTime: 'Day 1, Morning',
  worldStatus: 'active',
  lastUpdated: new Date().toISOString()
};

// Load existing world data if available
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  const dataRow = $input[1].json.values.find(row => row[0] === campaignId);

  if (dataRow) {
    currentWorldState = {
      campaignId: dataRow[0],
      locations: JSON.parse(dataRow[1] || '[]'),
      npcs: JSON.parse(dataRow[2] || '[]'),
      factions: JSON.parse(dataRow[3] || '[]'),
      quests: JSON.parse(dataRow[4] || '[]'),
      worldEvents: JSON.parse(dataRow[5] || '[]'),
      timelineEvents: JSON.parse(dataRow[6] || '[]'),
      currentInGameTime: dataRow[7] || 'Day 1, Morning',
      worldStatus: dataRow[8] || 'active',
      lastUpdated: dataRow[9] || new Date().toISOString()
    };
  }
}

// Process location changes
let updatedLocations = [...currentWorldState.locations];
locationChanges.forEach(change => {
  const { locationId, action: locAction, data } = change;
  const existingIndex = updatedLocations.findIndex(loc => loc.id === locationId);

  if (locAction === 'add' || locAction === 'create') {
    if (existingIndex === -1) {
      updatedLocations.push({
        id: locationId,
        name: data.name || locationId,
        description: data.description || '',
        type: data.type || 'location',
        coordinates: data.coordinates || { x: 0, y: 0 },
        connections: data.connections || [],
        properties: data.properties || {},
        discovered: data.discovered !== false,
        lastVisited: data.lastVisited || null,
        createdAt: new Date().toISOString()
      });
    }
  } else if (locAction === 'update' && existingIndex >= 0) {
    updatedLocations[existingIndex] = {
      ...updatedLocations[existingIndex],
      ...data,
      lastModified: new Date().toISOString()
    };
  } else if (locAction === 'delete' && existingIndex >= 0) {
    updatedLocations.splice(existingIndex, 1);
  }
});

// Process NPC changes
let updatedNPCs = [...currentWorldState.npcs];
npcChanges.forEach(change => {
  const { npcId, action: npcAction, data } = change;
  const existingIndex = updatedNPCs.findIndex(npc => npc.id === npcId);

  if (npcAction === 'add' || npcAction === 'create') {
    if (existingIndex === -1) {
      updatedNPCs.push({
        id: npcId,
        name: data.name || npcId,
        description: data.description || '',
        race: data.race || 'unknown',
        class: data.class || 'commoner',
        level: data.level || 1,
        location: data.location || 'unknown',
        relationships: data.relationships || {},
        faction: data.faction || 'neutral',
        status: data.status || 'alive',
        dialogue: data.dialogue || [],
        inventory: data.inventory || [],
        properties: data.properties || {},
        createdAt: new Date().toISOString()
      });
    }
  } else if (npcAction === 'update' && existingIndex >= 0) {
    updatedNPCs[existingIndex] = {
      ...updatedNPCs[existingIndex],
      ...data,
      lastModified: new Date().toISOString()
    };
  } else if (npcAction === 'delete' && existingIndex >= 0) {
    updatedNPCs.splice(existingIndex, 1);
  }
});

// Process faction changes
let updatedFactions = [...currentWorldState.factions];
factionChanges.forEach(change => {
  const { factionId, action: facAction, data } = change;
  const existingIndex = updatedFactions.findIndex(fac => fac.id === factionId);

  if (facAction === 'add' || facAction === 'create') {
    if (existingIndex === -1) {
      updatedFactions.push({
        id: factionId,
        name: data.name || factionId,
        description: data.description || '',
        type: data.type || 'organization',
        alignment: data.alignment || 'neutral',
        reputation: data.reputation || 0,
        members: data.members || [],
        territories: data.territories || [],
        relationships: data.relationships || {},
        resources: data.resources || {},
        goals: data.goals || [],
        createdAt: new Date().toISOString()
      });
    }
  } else if (facAction === 'update' && existingIndex >= 0) {
    updatedFactions[existingIndex] = {
      ...updatedFactions[existingIndex],
      ...data,
      lastModified: new Date().toISOString()
    };
  } else if (facAction === 'delete' && existingIndex >= 0) {
    updatedFactions.splice(existingIndex, 1);
  }
});

// Process quest changes
let updatedQuests = [...currentWorldState.quests];
questChanges.forEach(change => {
  const { questId, action: questAction, data } = change;
  const existingIndex = updatedQuests.findIndex(quest => quest.id === questId);

  if (questAction === 'add' || questAction === 'create') {
    if (existingIndex === -1) {
      updatedQuests.push({
        id: questId,
        name: data.name || questId,
        description: data.description || '',
        type: data.type || 'main',
        status: data.status || 'available',
        difficulty: data.difficulty || 'normal',
        objectives: data.objectives || [],
        rewards: data.rewards || {},
        prerequisites: data.prerequisites || [],
        location: data.location || 'unknown',
        giver: data.giver || 'unknown',
        timeLimit: data.timeLimit || null,
        progress: data.progress || 0,
        completedObjectives: data.completedObjectives || [],
        createdAt: new Date().toISOString()
      });
    }
  } else if (questAction === 'update' && existingIndex >= 0) {
    updatedQuests[existingIndex] = {
      ...updatedQuests[existingIndex],
      ...data,
      lastModified: new Date().toISOString()
    };
  } else if (questAction === 'delete' && existingIndex >= 0) {
    updatedQuests.splice(existingIndex, 1);
  }
});

// Process world events
let updatedWorldEvents = [...currentWorldState.worldEvents, ...worldEvents].map(event => ({
  ...event,
  id: event.id || `event_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
  timestamp: event.timestamp || new Date().toISOString()
}));

// Process timeline events
let updatedTimelineEvents = [...currentWorldState.timelineEvents, ...timelineEvents].map(event => ({
  ...event,
  id: event.id || `timeline_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
  timestamp: event.timestamp || new Date().toISOString()
}));

// Calculate world statistics
const worldStats = {
  totalLocations: updatedLocations.length,
  discoveredLocations: updatedLocations.filter(loc => loc.discovered).length,
  totalNPCs: updatedNPCs.length,
  aliveNPCs: updatedNPCs.filter(npc => npc.status === 'alive').length,
  totalFactions: updatedFactions.length,
  activeQuests: updatedQuests.filter(quest => ['available', 'active', 'in_progress'].includes(quest.status)).length,
  completedQuests: updatedQuests.filter(quest => quest.status === 'completed').length,
  totalWorldEvents: updatedWorldEvents.length,
  recentEvents: updatedWorldEvents.filter(event => {
    const eventTime = new Date(event.timestamp);
    const dayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);
    return eventTime > dayAgo;
  }).length
};

// Prepare updated world state
const updatedWorldState = {
  campaignId,
  locations: updatedLocations,
  npcs: updatedNPCs,
  factions: updatedFactions,
  quests: updatedQuests,
  worldEvents: updatedWorldEvents,
  timelineEvents: updatedTimelineEvents,
  currentInGameTime: currentWorldState.currentInGameTime,
  worldStatus: currentWorldState.worldStatus,
  worldStats,
  lastUpdated: new Date().toISOString(),
  metadata: {
    locationChanges: locationChanges.length,
    npcChanges: npcChanges.length,
    factionChanges: factionChanges.length,
    questChanges: questChanges.length,
    newWorldEvents: worldEvents.length,
    newTimelineEvents: timelineEvents.length,
    processedBy: 'world-state-processor'
  }
};

return { json: updatedWorldState };

// Format world state data for Google Sheets
const worldData = $input.first().json;

// Prepare row data in the correct order for Google Sheets
const rowData = [
  worldData.campaignId,
  JSON.stringify(worldData.locations),
  JSON.stringify(worldData.npcs),
  JSON.stringify(worldData.factions),
  JSON.stringify(worldData.quests),
  JSON.stringify(worldData.worldEvents),
  JSON.stringify(worldData.timelineEvents),
  worldData.currentInGameTime,
  worldData.worldStatus,
  worldData.lastUpdated
];

return {
  json: {
    range: 'Campaign_State!A:J',
    values: [rowData]
  }
};

// Send real-time world update to WebSocket system
const worldData = $input.first().json;
const { campaignId, metadata } = worldData;

// Prepare WebSocket broadcast payload
const broadcastPayload = {
  type: 'world_update',
  data: {
    campaignId,
    worldStats: worldData.worldStats,
    currentInGameTime: worldData.currentInGameTime,
    worldStatus: worldData.worldStatus,
    recentChanges: {
      locations: metadata.locationChanges || 0,
      npcs: metadata.npcChanges || 0,
      factions: metadata.factionChanges || 0,
      quests: metadata.questChanges || 0,
      worldEvents: metadata.newWorldEvents || 0,
      timelineEvents: metadata.newTimelineEvents || 0
    },
    lastUpdated: worldData.lastUpdated
  },
  channels: [`campaign_${campaignId}`, 'world_updates', 'dm_updates'],
  timestamp: new Date().toISOString()
};

// Send to WebSocket system
fetch('http://localhost:5678/webhook/websocket/broadcast', {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json'
  },
  body: JSON.stringify(broadcastPayload)
}).catch(error => {
  console.error('Failed to broadcast world update:', error);
});

return { json: { broadcast: 'sent', campaignId } };

