// Process relationship matrix updates
const relationshipData = $input.first().json;
const { 
  campaignId,
  relationshipType, // 'npc-npc', 'npc-faction', 'faction-faction', 'character-npc'
  entityId1,
  entityId2,
  relationshipChange, // 'improve', 'deteriorate', 'set'
  value,
  reason = ''
} = relationshipData;

// Validate required fields
if (!campaignId || !relationshipType || !entityId1 || !entityId2) {
  throw new Error('Missing required fields for relationship update');
}

// Prepare relationship update data
const relationshipUpdate = {
  campaignId,
  relationshipType,
  entityId1,
  entityId2,
  relationshipChange,
  value,
  reason,
  timestamp: new Date().toISOString(),
  action: 'relationship_update'
};

return { json: relationshipUpdate };

// Calculate relationship matrix updates
const relationshipData = $input.first().json;
const {
  campaignId,
  relationshipType,
  entityId1,
  entityId2,
  relationshipChange,
  value,
  reason
} = relationshipData;

// Get current relationships
let currentRelationships = [];
if ($input.length > 1 && $input[1].json && $input[1].json.values) {
  currentRelationships = $input[1].json.values.filter(row => row[0] === campaignId).map(row => ({
    campaignId: row[0],
    relationshipType: row[1],
    entityId1: row[2],
    entityId2: row[3],
    value: parseInt(row[4]) || 0,
    history: JSON.parse(row[5] || '[]')
  }));
}

// Find existing relationship
const existingIndex = currentRelationships.findIndex(
  rel => rel.relationshipType === relationshipType &&
         ((rel.entityId1 === entityId1 && rel.entityId2 === entityId2) ||
          (rel.entityId1 === entityId2 && rel.entityId2 === entityId1))
);

let updatedRelationship;
if (existingIndex >= 0) {
  // Update existing relationship
  const currentRel = currentRelationships[existingIndex];
  let newValue = currentRel.value;

  if (relationshipChange === 'improve') {
    newValue = Math.min(100, currentRel.value + value);
  } else if (relationshipChange === 'deteriorate') {
    newValue = Math.max(-100, currentRel.value - value);
  } else if (relationshipChange === 'set') {
    newValue = Math.max(-100, Math.min(100, value));
  }

  const historyEntry = {
    timestamp: new Date().toISOString(),
    change: relationshipChange,
    oldValue: currentRel.value,
    newValue: newValue,
    reason: reason || `Relationship changed via ${relationshipChange}`
  };

  updatedRelationship = {
    ...currentRel,
    value: newValue,
    history: [...currentRel.history, historyEntry]
  };

  currentRelationships[existingIndex] = updatedRelationship;
} else {
  // Create new relationship
  let newValue = 0;
  if (relationshipChange === 'set') {
    newValue = Math.max(-100, Math.min(100, value));
  } else if (relationshipChange === 'improve') {
    newValue = value;
  } else if (relationshipChange === 'deteriorate') {
    newValue = -value;
  }

  updatedRelationship = {
    campaignId,
    relationshipType,
    entityId1,
    entityId2,
    value: newValue,
    history: [{
      timestamp: new Date().toISOString(),
      change: relationshipChange,
      oldValue: 0,
      newValue: newValue,
      reason: reason || `Initial relationship established via ${relationshipChange}`
    }]
  };

  currentRelationships.push(updatedRelationship);
}

// Generate relationship summary
const relationshipSummary = {
  campaignId,
  relationshipType,
  entity1: entityId1,
  entity2: entityId2,
  currentValue: updatedRelationship.value,
  status: updatedRelationship.value > 50 ? 'friendly' : 
           updatedRelationship.value < -50 ? 'hostile' : 'neutral',
  recentChange: updatedRelationship.history[updatedRelationship.history.length - 1],
  totalHistory: updatedRelationship.history.length
};

return { json: { updatedRelationships: currentRelationships, summary: relationshipSummary } };

