// Data validation for world state operations
const worldData = $input.first().json;
const validationErrors = [];

// Validate campaign ID format
if (!worldData.campaignId || typeof worldData.campaignId !== 'string') {
  validationErrors.push('Invalid campaign ID format');
}

// Validate world status
if (worldData.worldStatus) {
  const validStatuses = ['active', 'paused', 'completed', 'archived'];
  if (!validStatuses.includes(worldData.worldStatus)) {
    validationErrors.push('Invalid world status');
  }
}

// Validate locations array
if (worldData.locations && !Array.isArray(worldData.locations)) {
  validationErrors.push('Locations must be an array');
} else if (worldData.locations) {
  worldData.locations.forEach((loc, index) => {
    if (!loc.id) validationErrors.push(`Location at index ${index} missing ID`);
    if (!loc.name) validationErrors.push(`Location at index ${index} missing name`);
  });
}

// Validate NPCs array
if (worldData.npcs && !Array.isArray(worldData.npcs)) {
  validationErrors.push('NPCs must be an array');
} else if (worldData.npcs) {
  worldData.npcs.forEach((npc, index) => {
    if (!npc.id) validationErrors.push(`NPC at index ${index} missing ID`);
    if (!npc.name) validationErrors.push(`NPC at index ${index} missing name`);
  });
}

// Validate factions array
if (worldData.factions && !Array.isArray(worldData.factions)) {
  validationErrors.push('Factions must be an array');
} else if (worldData.factions) {
  worldData.factions.forEach((faction, index) => {
    if (!faction.id) validationErrors.push(`Faction at index ${index} missing ID`);
    if (!faction.name) validationErrors.push(`Faction at index ${index} missing name`);
  });
}

// Validate quests array
if (worldData.quests && !Array.isArray(worldData.quests)) {
  validationErrors.push('Quests must be an array');
} else if (worldData.quests) {
  worldData.quests.forEach((quest, index) => {
    if (!quest.id) validationErrors.push(`Quest at index ${index} missing ID`);
    if (!quest.name) validationErrors.push(`Quest at index ${index} missing name`);
  });
}

// Return validation result
if (validationErrors.length > 0) {
  return {
    json: {
      valid: false,
      errors: validationErrors,
      campaignId: worldData.campaignId
    }
  };
}

return {
  json: {
    valid: true,
    worldData,
    campaignId: worldData.campaignId
  }
};
